import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"二次开发与自定义","description":"这一分区写给想改动 KomaYomi 本身的人：为某本杂志加一个分格识别插件、调整目录扫描规则、发布一套导出样式，或者直接改应用代码。下面每一处协议和字段都对照源码核对过；如果这里和代码对不上，以代码为准。","frontmatter":{"description":"这一分区写给想改动 KomaYomi 本身的人：为某本杂志加一个分格识别插件、调整目录扫描规则、发布一套导出样式，或者直接改应用代码。下面每一处协议和字段都对照源码核对过；如果这里和代码对不上，以代码为准。"},"headers":[],"relativePath":"zh/development/index.md","filePath":"zh/development/index.md","lastUpdated":1794841797000}'),a={name:"zh/development/index.md"};function r(s,e,i,l,n,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="二次开发与自定义" tabindex="-1">二次开发与自定义 <a class="header-anchor" href="#二次开发与自定义" aria-label="Permalink to &quot;二次开发与自定义&quot;">​</a></h1><p>这一分区写给想改动 KomaYomi 本身的人：为某本杂志加一个分格识别插件、调整目录扫描规则、发布一套导出样式，或者直接改应用代码。下面每一处协议和字段都对照源码核对过；如果这里和代码对不上，以代码为准。</p><p>只想看漫画、做笔记的话，请从<a href="/KomaYomi-docs/zh/guide/introduction">使用指南</a>开始。</p><h2 id="本分区包含什么" tabindex="-1">本分区包含什么 <a class="header-anchor" href="#本分区包含什么" aria-label="Permalink to &quot;本分区包含什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>回答的问题</th></tr></thead><tbody><tr><td>本页</td><td>前端、服务端、共享层各管什么，哪些能力只有本地版才有。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/data-formats">数据格式</a></td><td>JSON 信封、页面文档、<code>library.json</code>、<code>.mnproj</code>、<code>.mntpl</code>、<code>.mnexp</code>，以及版本迁移和未知字段规则。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/plugins">分格插件</a></td><td>插件的真实协议、可直接运行的例子、怎么试跑、出错时看哪个错误码。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/folder-rules">目录规则</a></td><td>占位符、可选段、通配、<code>ignore</code>、<code>extensions</code>，以及几种常见目录结构的完整写法。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/export-templates">导出模板</a></td><td>模板能存哪些字段、完整的 <code>.mnexp</code> 示例、怎么套用。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/build">构建与打包</a></td><td>开发服务、生产构建、独立服务、Electron、Docker 与静态在线版的差别。</td></tr><tr><td><a href="/KomaYomi-docs/zh/development/contributing">贡献指南</a></td><td>分支与提交规范、检查命令，以及一个最小改动的完整示例。</td></tr></tbody></table><h2 id="仓库结构" tabindex="-1">仓库结构 <a class="header-anchor" href="#仓库结构" aria-label="Permalink to &quot;仓库结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>负责什么</th></tr></thead><tbody><tr><td><code>src/</code></td><td>React 18 前端：图库侧栏、切格工作台、对照阅读、笔记、导出对话框、各类弹窗与多语言文案。</td></tr><tr><td><code>server/</code></td><td>Node HTTP API 和全部本地能力：图库扫描、分格检测、布局模板、插件、对齐预设、导出、备份、存储、版本历史。</td></tr><tr><td><code>shared/</code></td><td>前后端共用：领域类型、JSON 信封与迁移、分格排序、Markdown 渲染。</td></tr><tr><td><code>electron/</code></td><td>Electron 主进程和数据目录处理。</td></tr><tr><td><code>scripts/</code></td><td>批量 CLI（<code>manga-cli.ts</code>）、服务端打包脚本、i18n 扫描、检测基线。</td></tr><tr><td><code>plugins/</code></td><td>可选的分格插件目录；也可以放在 <code>data/plugins/</code>。</td></tr><tr><td><code>docs/</code></td><td>当前这个 VitePress 文档站，有独立的 <code>package.json</code>。</td></tr><tr><td><code>raw/</code>、<code>data/</code>、<code>exports/</code></td><td>你的图片、你的 JSON、生成的文件，都不进仓库。</td></tr></tbody></table><h2 id="三层各做什么" tabindex="-1">三层各做什么 <a class="header-anchor" href="#三层各做什么" aria-label="Permalink to &quot;三层各做什么&quot;">​</a></h2><h3 id="前端-src" tabindex="-1">前端 <code>src/</code> <a class="header-anchor" href="#前端-src" aria-label="Permalink to &quot;前端 `src/`&quot;">​</a></h3><p>一个由 Vite 构建的 React 单页应用。<code>src/App.tsx</code> 负责整体框架：顶栏、侧栏、主舞台、笔记栏和分隔条；具体功能放在 <code>src/components/</code>。<code>src/api.ts</code> 是唯一和后端通信的地方，所有请求都是对相对路径 <code>/api/...</code> 的 <code>fetch</code>。因此前端不知道自己是跑在 Vite、独立服务还是 Electron 里。</p><p>图库、当前页面文档、已保存的模板这些属于服务端的状态，都通过 <code>src/api.ts</code> 读取，再显式写回。正常使用时浏览器里没有本地数据库。</p><h3 id="服务端-server" tabindex="-1">服务端 <code>server/</code> <a class="header-anchor" href="#服务端-server" aria-label="Permalink to &quot;服务端 `server/`&quot;">​</a></h3><p>只有一个路由函数：<code>server/app.ts</code> 里的 <code>createMangaHandler({ rootDir })</code> 根据 <code>pathname</code> 和 <code>method</code> 分派到各领域模块。同一个 handler 跑在三种宿主里：</p><table tabindex="0"><thead><tr><th>宿主</th><th>入口</th><th>怎么访问</th></tr></thead><tbody><tr><td>开发与预览</td><td><code>server/plugin.ts</code></td><td>挂成 Vite 中间件，地址 <code>127.0.0.1:5173</code>，不需要另起进程。</td></tr><tr><td>独立服务 / Docker</td><td><code>server/standalone.ts</code></td><td><code>npm start</code>，端口 <code>3921</code>，可用 <code>RAW_DIR</code>、<code>DATA_DIR</code>、<code>EXPORT_DIR</code> 改目录。</td></tr><tr><td>桌面版</td><td><code>dist-server/app.mjs</code></td><td><code>scripts/build-server.mjs</code> 打包后由 <code>electron/main.cjs</code> 加载。</td></tr></tbody></table><p>模块划分刻意做窄：<code>library.ts</code> 扫描并组织页面，<code>dirRules.ts</code> 把路径模式变成页面记录，<code>detect.ts</code> 是 XY-cut 检测器，<code>plugins.ts</code> 运行插件，<code>layouts.ts</code> 展开声明式网格，<code>storage.ts</code> 负责页面读写，<code>schemaStore.ts</code> 负责迁移与原子写入，<code>export.ts</code> 与 <code>exportDocx.ts</code> 生成文档，<code>project.ts</code> 和 <code>backup.ts</code> 处理工程包与 ZIP。</p><h3 id="共享层-shared" tabindex="-1">共享层 <code>shared/</code> <a class="header-anchor" href="#共享层-shared" aria-label="Permalink to &quot;共享层 `shared/`&quot;">​</a></h3><p><code>shared/</code> 不能依赖 Node 专有 API，也不能碰 DOM，否则总有一端用不了。</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td><code>PageDoc</code>、<code>Panel</code>、<code>Note</code>、<code>Annotation</code>、阅读方向、导出配置、图库类型。</td></tr><tr><td><code>format.ts</code></td><td><code>$schema</code> / <code>schemaVersion</code> 信封、各格式校验、迁移分派、<code>preserveUnknown</code>。</td></tr><tr><td><code>migrations.ts</code></td><td>纯函数式的 v0 → v1 迁移，不读写磁盘。</td></tr><tr><td><code>panelOrder.ts</code></td><td>显示、导出和 CLI 共用的阅读顺序与分组顺序。</td></tr><tr><td><code>markdown.ts</code></td><td>Markdown 渲染，原始 HTML 会被转义。</td></tr><tr><td><code>schemas/*.json</code></td><td>便于阅读的 JSON Schema 镜像；运行时以代码里的校验器为准。</td></tr></tbody></table><h2 id="一次请求怎么走" tabindex="-1">一次请求怎么走 <a class="header-anchor" href="#一次请求怎么走" aria-label="Permalink to &quot;一次请求怎么走&quot;">​</a></h2><p><strong>读取图库。</strong> 侧栏请求 <code>GET /api/library</code>。<code>server/app.ts</code> 收到后交给 <code>server/library.ts</code>：读 <code>data/library.json</code>，用 <code>server/dirRules.ts</code> 解析规则，遍历 <code>raw/</code>（或映射后的远端目录），按 卷 → 章 → 页 分组，最后返回 JSON。整个过程不写盘。</p><p><strong>保存页面。</strong> 工作台用 <code>PUT /api/page</code> 提交整份页面文档。<code>server/app.ts</code> 先校验基本结构，然后由 <code>server/storage.ts</code> 的 <code>writePageDoc</code> 依次做五件事：</p><ol><li>文件来自更新版本时拒绝写入（<code>409</code>，<code>ERR_SCHEMA_TOO_NEW</code>）；</li><li>规范化矩形、笔记、偏移和 id；</li><li>用 <code>preserveUnknown</code> 把上一版里的未知字段合并回来；</li><li>经 <code>server/schemaStore.ts</code> 原子写入；</li><li>除非调用方要求跳过，否则记录一份版本快照。</li></ol><p><strong>检测分格。</strong> <code>POST /api/detect</code> 先找绑定到该页、该章或该卷的布局模板，再找第一个匹配的插件，最后才用内建检测器。结果会和 <code>detectSource</code>、<code>detectorVersion</code> 一起写回去，方便以后判断这些格框是谁给的。</p><h2 id="只有本地版才有的能力" tabindex="-1">只有本地版才有的能力 <a class="header-anchor" href="#只有本地版才有的能力" aria-label="Permalink to &quot;只有本地版才有的能力&quot;">​</a></h2><p>桌面版和本地服务版能读文件、能起进程，所以下面这些能力静态在线版没有：</p><table tabindex="0"><thead><tr><th>能力</th><th>本地网页 / 桌面版</th><th>静态在线版</th></tr></thead><tbody><tr><td>扫描 <code>raw/</code> 下的目录</td><td>有</td><td>没有，浏览器无法遍历目录树。</td></tr><tr><td>自动分格检测</td><td>有</td><td>尚未移植。</td></tr><tr><td>布局模板与插件</td><td>有</td><td>没有，两者都跑在服务端进程里。</td></tr><tr><td>WebDAV / 网络存储与图片缓存</td><td>有</td><td>没有。</td></tr><tr><td>备份 ZIP、工程导入导出</td><td>有</td><td>能打开工程文件，没有目录备份。</td></tr><tr><td>数据存在哪</td><td>图片旁边的 <code>data/</code></td><td>浏览器的 IndexedDB</td></tr></tbody></table><p>静态在线版是另一个仓库，仍在开发中：<code>https://github.com/PayayaKamo/KomaYomi-online</code>。本仓库只构建本地版。共享与不共享的边界见<a href="/KomaYomi-docs/zh/development/build#静态在线版">构建与打包</a>。</p><h2 id="几条约定" tabindex="-1">几条约定 <a class="header-anchor" href="#几条约定" aria-label="Permalink to &quot;几条约定&quot;">​</a></h2><ul><li>服务端是纯 ESM TypeScript，开发时由 Node 的类型剥离直接运行；import 要带 <code>.ts</code> 后缀。</li><li>没有数据库。所有持久化内容都是 JSON 文件，写入是原子的。</li><li>面向用户的提示放在 <code>server/messages/catalog.ts</code>，前端文案放在 <code>src/i18n/</code>。在组件里写死中文会被 <code>npm run i18n:scan</code> 判为问题。</li><li>文档站三语同构。新增页面要同时有 <code>docs/&lt;page&gt;.md</code>、<code>docs/zh/&lt;page&gt;.md</code>、<code>docs/ja/&lt;page&gt;.md</code>，并在 <code>docs/.vitepress/config.mts</code> 里补上导航和侧栏。</li></ul><h2 id="从哪里下手" tabindex="-1">从哪里下手 <a class="header-anchor" href="#从哪里下手" aria-label="Permalink to &quot;从哪里下手&quot;">​</a></h2><ul><li>改页面在磁盘上怎么找：看<a href="/KomaYomi-docs/zh/development/folder-rules">目录规则</a>。</li><li>给某本杂志换检测方式：看<a href="/KomaYomi-docs/zh/development/plugins">分格插件</a>。</li><li>写工具读写 KomaYomi 数据：看<a href="/KomaYomi-docs/zh/development/data-formats">数据格式</a>。</li><li>直接改应用本身：看<a href="/KomaYomi-docs/zh/development/contributing">贡献指南</a>。</li></ul>',31)])])}const b=d(a,[["render",r]]);export{m as __pageData,b as default};
